#include <iostream>
#include <stdexcept>
using namespace std;
long long countWork(int n, int power) {
    if (n < 1 || n > 65536 || (n & (n-1)) || power < 0 || power > 2)
        throw invalid_argument("Use power-of-two n in [1,65536], power in [0,2]");
    if (n == 1) return 1; // one unit per leaf
    long long total = countWork(n/2,power) + countWork(n/2,power);
    long long own = power == 0 ? 1 : power == 1 ? n : 1LL*n*n;
    return total; // TODO: 加上自身工作 own
}
int main() {
    int ns[] = {1,2,8,8,8,16,16,1};
    int powers[] = {0,0,0,1,2,1,2,2};
    long long expected[] = {1,3,15,32,120,80,496,1};
    int passed=0;
    for(int k=0;k<8;++k) {
        auto actual=countWork(ns[k],powers[k]);
        bool ok=actual==expected[k];passed+=ok;
        cout<<(ok?"PASS":"FAIL")<<" n="<<ns[k]<<" power="<<powers[k]
            <<" expected="<<expected[k]<<" got="<<actual<<endl;
    }
    cout<<passed<<"/8 passed"<<endl;
}
